import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"About Memoh","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1790952322000}'),r={name:"about.md"};function n(i,e,l,h,c,d){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="about-memoh" tabindex="-1">About Memoh <a class="header-anchor" href="#about-memoh" aria-label="Permalink to &quot;About Memoh&quot;">​</a></h1><p>Memoh v0.13 is the open-source multi-agent platform. It lets you run multiple AI agents on one machine, with each agent getting its own workspace, browser, network, tools, and long-term memory.</p><p>Agents can talk through Telegram, Discord, Slack, Feishu, WeChat, DingTalk, and other channels — and directly in the Memoh app. They can remember context, operate a browser or desktop, call MCP tools, install skills and connectors, run scheduled tasks, and enforce per-bot access rules.</p><p>Prefer a managed option instead of operating your own deployment? <a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> runs the same product as a hosted service.</p><h2 id="distribution-modes" tabindex="-1">Distribution Modes <a class="header-anchor" href="#distribution-modes" aria-label="Permalink to &quot;Distribution Modes&quot;">​</a></h2><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>Desktop is the native client for Memoh Cloud or a self-hosted server. It wraps the same client interface in a native window with a system tray and shortcuts, and can register the computer it runs on as a Computer that bots may use. It does not run a local server.</p><h3 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h3><p>Server Deploy is for always-on shared usage. Use it when Memoh should serve multiple users, keep channels online while your computer is offline, or run as a self-hosted service. The Docker Compose stack includes the backend, web client, database, memory services, and workspace runtime.</p><h2 id="what-v0-13-emphasizes" tabindex="-1">What v0.13 Emphasizes <a class="header-anchor" href="#what-v0-13-emphasizes" aria-label="Permalink to &quot;What v0.13 Emphasizes&quot;">​</a></h2><h3 id="agent-workspaces" tabindex="-1">Agent Workspaces <a class="header-anchor" href="#agent-workspaces" aria-label="Permalink to &quot;Agent Workspaces&quot;">​</a></h3><p>Each bot can use an isolated container workspace with files, commands, MCP hosting, network access, a headed browser, and a graphical desktop. Local and desktop setups can also use trusted local workspaces when host-level access is intentional.</p><h3 id="the-client" tabindex="-1">The Client <a class="header-anchor" href="#the-client" aria-label="Permalink to &quot;The Client&quot;">​</a></h3><p>The client now covers more of the daily product surface: bot setup, sessions, providers, channels, workspace files, terminal and desktop panes, Supermarket, hooks, schedules, access control, and user preferences. v0.13 also includes English, Simplified Chinese, and Japanese UI language support.</p><h3 id="hooks-schedules-and-automation" tabindex="-1">Hooks, Schedules, And Automation <a class="header-anchor" href="#hooks-schedules-and-automation" aria-label="Permalink to &quot;Hooks, Schedules, And Automation&quot;">​</a></h3><p>Hooks let bots run small automation rules around supported events, while Schedule keeps recurring work moving without an active chat. Skills and connectors from the Supermarket extend what a bot can do without custom code.</p><h3 id="access-control" tabindex="-1">Access Control <a class="header-anchor" href="#access-control" aria-label="Permalink to &quot;Access Control&quot;">​</a></h3><p>Access control is split between channel-side chat permissions and workspace-side user permissions. Bot owners can allow or block channel members, grant registered users workspace roles, and keep advanced ACL rules for cases that need more precise matching.</p><h2 id="where-to-start" tabindex="-1">Where To Start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where To Start&quot;">​</a></h2><ul><li><strong><a href="./guides/working-with-bots.html">Bot Setup</a></strong> - create and configure a bot.</li><li><strong><a href="./integrations/providers/llm.html">Providers And Models</a></strong> - configure model access.</li><li><strong><a href="./integrations/channels/">Channels</a></strong> - choose where bots are reachable.</li><li><strong><a href="./guides/skills.html">Skills</a></strong> and <strong><a href="./guides/supermarket.html">Supermarket</a></strong> - install reusable capabilities.</li><li><strong><a href="./guides/schedule.html">Scheduled Tasks</a></strong> and <strong><a href="./guides/access.html">Access Control</a></strong> - operate recurring work and permissions.</li><li><strong><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Help Center</a></strong> - plans, billing, and account questions, plus a direct line to the team.</li></ul>',20)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
